168	}
169	
170	.badge {
171	  position: absolute;
172	  top: -10px;
173	  right: -10px;
174	  padding: 3px 10px;
175	  border-radius: var(--radius-pill);
176	  background: var(--color-brand);
177	  color: #ffffff;
178	  font-size: 12px;
179	  font-weight: 700;
180	}
181	
182	.badge-sale {
183	  background: var(--color-danger);
184	}
185	
186	.price {
187	  font-size: 20px;
188	  font-weight: 800;
189	  color: var(--color-brand);
190	}
191	
192	/* Stat */
193	
194	.stats {
195	  display: grid;
196	  grid-template-columns: repeat(3, 1fr);
197	  gap: var(--space-4);
