205	  box-shadow: var(--shadow-md);
206	}
207	
208	.stat-value {
209	  font-size: 28px;
210	  font-weight: 800;
211	  line-height: 1.2;
212	  letter-spacing: -0.02em;
213	}
214	
215	.stat-label {
216	  font-size: 14px;
217	  color: var(--color-muted);
218	}
219	
220	/* Form */
221	
222	.form .btn {
223	  min-width: 140px;
224	}
225	
226	.form-field {
227	  margin-bottom: var(--space-4);
228	}
229	
230	.form-label {
231	  display: block;
232	  margin-bottom: var(--space-1);
233	  font-size: 14px;
234	  font-weight: 600;
235	}
236	
237	.form-input {
