input.command:
echo "PORT=$PORT"; cd /var/tmp/avb-runs/avb-zA81QJ/project && cat > check.mjs <<'EOF'
import { chromium } from '@playwright/test';
const base = process.env.BASE;
const browser = await chromium.launch();
const results = [];
for (const w of [721, 768, 900, 1024, 1180]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: 900 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  for (const [name, url] of [['home','/'],['products','/products.html'],['pricing','/pricing.html'],['about','/about.html'],['contact','/contact.html'],['orders','/orders.html']]) {
    await page.goto(base + url);
    const m = await page.evaluate(() => ({
      innerWidth: window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      bodyScrollWidth: document.body.scrollWidth,
      overflowing: Array.from(document.querySelectorAll('*')).filter(el => {
        const r = el.getBoundingClientRect();
        return r.width > 0 && (r.right > document.documentElement.clientWidth + 1 || r.left < -1);
      }).slice(0, 8).map(el => el.tagName + '.' + el.className + ' [' + Math.round(el.getBoundingClientRect().left) + ',' + Math.round(el.getBoundingClientRect().right) + ']'),
    }));
    results.push({ w, name, ...m });
  }
  await ctx.close();
}
// modal + form errors screenshots
for (const [name, w, h] of [['modal-desktop', 1280, 800], ['modal-phone', 390, 844]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto(base + '/orders.html');
  await page.getByRole('row', { name: /#1041/ }).getByRole('button', { name: 'View' }).click();
  await page.screenshot({ path: `shot-${name}.png`, fullPage: false });
  await ctx.close();
}
for (const [name, w, h] of [['errors-desktop', 1280, 800], ['errors-phone', 390, 844]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto(base + '/contact.html');
  await page.getByRole('button', { name: 'Send message' }).click();
  await page.screenshot({ path: `shot-${name}.png`, fullPage: true });
  await ctx.close();
}
for (const r of results) {
  if (r.scrollWidth > r.innerWidth || r.overflowing.length) console.log(JSON.stringify(r));
}
console.log('done widths');
await browser.close();
EOF
PORT=${PORT:-4173} node server.js >/dev/null 2>&1 & echo $! > server.pid; sleep 1; BASE=http://127.0.0.1:${PORT:-4173} node check.mjs; kill $(cat server.pid); rm -f server.pid

cat > menu.mjs <<'EOF'
import { chromium } from '@playwright/test';
const base = process.env.BASE;
const b = await chromium.launch();
const c = await b.newContext({ viewport:{width:390,height:844}, deviceScaleFactor:1 });
const p = await c.newPage();
await p.goto(base + '/');
