cat > consolecheck.mjs <<'EOF'
import { chromium } from '@playwright/test';
const base = process.env.BASE;
const b = await chromium.launch();
for (const url of ['/','/products.html','/pricing.html','/orders.html','/about.html','/contact.html']) {
  const ctx = await b.newContext({viewport:{width:1280,height:800}});
  const p = await ctx.newPage();
  const errs=[]; p.on('console',m=>{if(m.type()==='error')errs.push('console: '+m.text())});
  p.on('pageerror',e=>errs.push('pageerror: '+e.message));
  p.on('requestfailed',r=>errs.push('reqfail: '+r.url()+' '+r.failure()?.errorText));
  const resp = await p.goto(base+url);
  await p.waitForTimeout(300);
  console.log(url, resp.status(), JSON.stringify(errs));
  await ctx.close();
}
await b.close();
EOF
PORT=${PORT:-4173} node server.js >/dev/null 2>&1 & echo $! > server.pid; sleep 1; BASE=http://127.0.0.1:${PORT:-4173} node consolecheck.mjs; kill $(cat server.pid); rm -f server.pid; rm -f check.mjs menu.mjs consolecheck.mjs shot-*.png

cat > midsize.mjs <<'EOF'
import { chromium } from '@playwright/test';
const base = process.env.BASE;
const b = await chromium.launch();
for (const w of [820, 900, 1024]) {
  const ctx = await b.newContext({viewport:{width:w,height:900}, deviceScaleFactor:1});
  const p = await ctx.newPage();
  for (const [n,u] of [['home','/'],['about','/about.html'],['contact','/contact.html'],['products','/products.html'],['pricing','/pricing.html'],['orders','/orders.html']]) {
    await p.goto(base+u);
    await p.screenshot({path:`mid-${n}-${w}.png`, fullPage:true});
  }
  await ctx.close();
}
await b.close();
EOF
PORT=${PORT:-4173} node server.js >/dev/null 2>&1 & echo $! > server.pid; sleep 1; BASE=http://127.0.0.1:${PORT:-4173} node midsize.mjs; kill $(cat server.pid); rm -f server.pid midsize.mjs; ls mid-*.png | head

